 if($action==='security'){
  $username=trim((string)($_POST['username']??''));$current=(string)($_POST['current_password']??'');$new=(string)($_POST['new_password']??'');$confirm=(string)($_POST['confirm_password']??'');
  $st=db()->prepare('SELECT password_hash FROM users WHERE id=:id');$st->execute([':id'=>$uid]);$hash=(string)$st->fetchColumn();
  if(!valid_username($username))flash('error','Choose a valid username (3–30 letters, numbers, dots, underscores or hyphens).');
