  elseif($new!==$confirm)flash('error','The new passwords do not match.');
  else{db()->prepare('UPDATE users SET username=:u,password_hash=:p WHERE id=:id')->execute([':u'=>$username,':p'=>password_hash($new,PASSWORD_DEFAULT),':id'=>$uid]);flash('success','Your username and password were updated. Use the new username next time you sign in.');}
  redirect(app_path('account.php'));
 }
 $phone=trim((string)($_POST['phone']??''));$homeCity=trim((string)($_POST['home_city']??''));$interests=trim((string)($_POST['interests']??''));$visibility=(string)($_POST['profile_visibility']??'public');$lang=(string)($_POST['language']??'en');if(!in_array($lang,['en','hi','bn'],true))$lang='en';if(!in_array($visibility,['public','private'],true))$visibility='public';db()->prepare('UPDATE users SET phone=:p,home_city=:city,interests=:interests,profile_visibility=:visibility,preferred_language=:l WHERE id=:id')->execute([':p'=>text_substr($phone,0,30),':city'=>text_substr($homeCity,0,120),':interests'=>text_substr($interests,0,300),':visibility'=>$visibility,':l'=>$lang,':id'=>$uid]);$_SESSION['language']=$lang;flash('success','Your profile preferences were updated.');redirect(app_path('account.php'));
}
